target.css:
:root {
  --card-bg: #1c1410;
  --card-border: #6b4c2a;
  --header-bg: #2e1d0e;
  --accent-gold: #c9963a;
  --accent-gold-light: #e8be6f;
  --text-primary: #f2e8d9;
  --text-secondary: #a8906e;
  --text-muted: #7a6248;
  --course-border: #3a2a18;
  --course-hover: #251a0f;
  --num-color: #c9963a;
  --tag-cold-bg: #1a2e3a;
  --tag-cold-text: #6db8d8;
  --tag-hot-bg: #3a1a10;
  --tag-hot-text: #e87a4a;
  --tag-room-bg: #2a2a18;
  --tag-room-text: #b8b86a;
  --footer-bg: #2e1d0e;
  --divider: #4a3420;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  margin: 0;
  padding: 20px;
  box-sizing: border-box;
}

.menu-card {
  background-color: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: 12px;
  width: 500px;
  overflow: hidden;
}

.menu-header {
  background-color: var(--header-bg);
  text-align: center;
  padding: 16px 24px 12px;
  border-bottom: 1px solid var(--divider);
}

.menu-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 3px;
  color: var(--accent-gold);
  text-transform: uppercase;
  display: block;
  margin-bottom: 4px;
}

.menu-title {
  font-size: 26px;
  font-weight: 700;
  color: var(--accent-gold-light);
  margin: 0 0 2px;
  letter-spacing: 1px;
}

.menu-subtitle {
  font-size: 12px;
  color: var(--text-secondary);
  margin: 0;
  letter-spacing: 1px;
}

.courses {
  padding: 8px 0;
}

.course {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 9px 20px;
  border-bottom: 1px solid var(--course-border);
}

.course:last-child {
  border-bottom: none;
}

.course-num {
  font-size: 11px;
  font-weight: 700;
  color: var(--num-color);
  width: 22px;
  flex-shrink: 0;
}

.course-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.course-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
}

.course-desc {
  font-size: 11px;
  color: var(--text-muted);
}

.course-tag {
  font-size: 10px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  flex-shrink: 0;
}

.tag-cold {
  background-color: var(--tag-cold-bg);
  color: var(--tag-cold-text);
}

.tag-hot {
  background-color: var(--tag-hot-bg);
  color: var(--tag-hot-text);
}

.tag-room {
  background-color: var(--tag-room-bg);
  color: var(--tag-room-text);
}

.menu-footer {
  background-color: var(--footer-bg);
  border-top: 1px solid var(--divider);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 20px;
}

.footer-price {
  font-size: 15px;
  font-weight: 700;
  color: var(--accent-gold-light);
}

.footer-note {
  font-size: 12px;
  color: var(--text-secondary);
}

